def make_important_html(plain_text):
    """
    Превращает обычный текст предупреждений в аккуратный HTML для QTextEdit/QTextBrowser.

    Зачем так сделано:
    - сам текст остаётся обычным и редактируемым в important_text;
    - заголовки пунктов автоматически становятся крупнее и жирнее;
    - строки "Решение:" / "Рішення:" / "Solution:" подсвечиваются;
    - списки с дефисом превращаются в HTML-списки.
    """
    if not plain_text:
        return ""

    solution_prefixes = (
        "Решение:",
        "Рішення:",
        "Solution:",
        "解决方法：",
        "解決方法：",
        "対処：",
    )

    parts = [
        "<html><head><style>",
        "body { font-family: 'Segoe UI', Arial, sans-serif; font-size: 11pt; color: #111111; }",
        "p { margin: 6px 0 9px 0; line-height: 1.35; }",
        ".section-title { margin-top: 14px; margin-bottom: 8px; padding: 7px 9px; "
        "font-size: 13pt; font-weight: 700; color: #263238; background: #f5f5f5; "
        "border-left: 4px solid #607d8b; }",
        ".section-title.critical { color: #b71c1c; background: #ffebee; border-left: 4px solid #b71c1c; }",
        ".solution { margin: 7px 0 12px 0; padding: 7px 9px; background: #f1f8e9; "
        "border-left: 4px solid #558b2f; }",
        "ul { margin-top: 4px; margin-bottom: 10px; }",
        "li { margin-bottom: 4px; }",
        "</style></head><body>",
    ]

    in_list = False
    lines = plain_text.splitlines()

    def close_list_if_needed():
        nonlocal in_list
        if in_list:
            parts.append("</ul>")
            in_list = False

    for raw_line in lines:
        line = raw_line.strip()
        if not line:
            continue

        # Заголовок пункта: "1. ...", "2. ..." и т.д.
        if line[0].isdigit() and ". " in line[:5]:
            close_list_if_needed()
            css_class = "section-title critical" if line.startswith("1.") else "section-title"
            parts.append(f"<div class='{css_class}'>{html.escape(line)}</div>")
            continue

        # Список с дефисами.
        if line.startswith("- "):
            if not in_list:
                parts.append("<ul>")
                in_list = True
            parts.append(f"<li>{html.escape(line[2:].strip())}</li>")
            continue

        close_list_if_needed()

        matched_solution_prefix = None
        for prefix in solution_prefixes:
            if line.startswith(prefix):
                matched_solution_prefix = prefix
                break

        if matched_solution_prefix:
            rest = line[len(matched_solution_prefix):].strip()
            parts.append(
                "<p class='solution'><b>"
                + html.escape(matched_solution_prefix)
                + "</b> "
                + html.escape(rest)
                + "</p>"
            )
        else:
            parts.append(f"<p>{html.escape(line)}</p>")

    close_list_if_needed()
    parts.append("</body></html>")
    return "".join(parts)


# HTML-версии предупреждений создаются автоматически из plain-text версий.
# Если текст important_text меняется, HTML обновится при следующем запуске приложения.
for _lang_data in TRANSLATIONS.values():
    if "important_text" in _lang_data:
        _lang_data["important_html"] = make_important_html(_lang_data["important_text"])

