def normalize_interface_lang(lang):
    """Возвращает поддерживаемый код языка интерфейса."""
    lang = str(lang or "").lower().strip().replace("-", "_")
    lang = {
        "zh_cn": "zh",
        "zh_s": "zh",
        "zh_hans": "zh",
        "zh_tw": "zh_hant",
        "zh_t": "zh_hant",
        "zh_hk": "zh_hant",
        "jp": "ja",
    }.get(lang, lang)
    return lang if lang in SUPPORTED_INTERFACE_LANGS else "uk"


def next_interface_lang(lang):
    """Циклически переключает язык интерфейса по общему списку локалей."""
    lang = normalize_interface_lang(lang)
    order = SUPPORTED_INTERFACE_LANGS
    return order[(order.index(lang) + 1) % len(order)]


def tr(lang, key, **kwargs):
    """Получить локализованную строку с безопасным fallback."""
    lang = normalize_interface_lang(lang)
    text = TRANSLATIONS.get(lang, {}).get(key)
    if not isinstance(text, str) or not text.strip():
        for fallback_lang in ("uk", "ru", "en"):
            fallback = TRANSLATIONS.get(fallback_lang, {}).get(key)
            if isinstance(fallback, str) and fallback.strip():
                text = fallback
                break
        else:
            text = str(key or "")
    try:
        return text.format(**kwargs)
    except Exception:
        return text


def interface_lang_button_text(lang):
    """Текст на кнопке языка. Иконка задаётся отдельно через PNG-файл."""
    lang = normalize_interface_lang(lang)
    return tr(
        lang,
        "interface_language_button",
        short=LANG_SHORT.get(lang, lang.upper()),
    )


def interface_lang_icon_file(lang):
    """Имя PNG-файла иконки языка из папки assets/icons."""
    lang = normalize_interface_lang(lang)
    return LANG_ICON_FILES.get(lang, "")


